from datetime import datetime


_KNOWN_LEVELS = frozenset(("INFO", "WARN", "ERROR"))


def parse_log_line(s):
    """'TIMESTAMP LEVEL MSG' 문자열을 (timestamp, level, msg) 튜플로 파싱한다."""
    if not isinstance(s, str):
        raise TypeError("s must be a str")

    line = s.strip()
    if not line:
        raise ValueError("log line must not be empty")

    parts = line.split(maxsplit=2)
    if len(parts) < 3:
        raise ValueError("log line must contain TIMESTAMP, LEVEL and MSG")

    ts, level, msg = parts

    if not msg or not msg.strip():
        raise ValueError("msg must not be empty")

    if level not in _KNOWN_LEVELS:
        raise ValueError(f"unknown level: {level!r}")

    if not _is_iso8601(ts):
        raise ValueError(f"invalid ISO8601 timestamp: {ts!r}")

    return (ts, level, msg)


def _is_iso8601(ts):
    candidate = ts
    if candidate.endswith(("Z", "z")):
        candidate = candidate[:-1] + "+00:00"
    try:
        datetime.fromisoformat(candidate)
